    map['is_subscription'] = Variable<bool>(isSubscription);
    map['reminder_offsets'] = Variable<String>(reminderOffsets);
    map['is_active'] = Variable<bool>(isActive);
    map['created_at'] = Variable<DateTime>(createdAt);
    return map;
  }

