            bool salaryPlansRefs,
          })
        > {
  $$TransactionsTableTableManager(_$AppDatabase db, $TransactionsTable table)
    : super(
        TableManagerState(
          db: db,
          table: table,
          createFilteringComposer:
              () => $$TransactionsTableFilterComposer($db: db, $table: table),
          createOrderingComposer:
              () => $$TransactionsTableOrderingComposer($db: db, $table: table),
          createComputedFieldComposer:
              () =>
                  $$TransactionsTableAnnotationComposer($db: db, $table: table),
          updateCompanionCallback:
              ({
                Value<String> id = const Value.absent(),
                Value<String> type = const Value.absent(),
                Value<int> amount = const Value.absent(),
                Value<String> currency = const Value.absent(),
                Value<String> description = const Value.absent(),
                Value<String?> merchant = const Value.absent(),
                Value<DateTime> occurredAt = const Value.absent(),
                Value<String> source = const Value.absent(),
                Value<String> status = const Value.absent(),
                Value<String?> primaryWalletId = const Value.absent(),
                Value<String?> destinationWalletId = const Value.absent(),
                Value<String?> primaryCategoryId = const Value.absent(),
                Value<String?> relatedTransactionId = const Value.absent(),
                Value<String?> importBatchId = const Value.absent(),
                Value<String?> idempotencyKey = const Value.absent(),
                Value<String?> location = const Value.absent(),
                Value<DateTime> createdAt = const Value.absent(),
                Value<DateTime> updatedAt = const Value.absent(),
                Value<int> rowid = const Value.absent(),
              }) => TransactionsCompanion(
                id: id,
                type: type,
                amount: amount,
                currency: currency,
                description: description,
                merchant: merchant,
                occurredAt: occurredAt,
                source: source,
                status: status,
                primaryWalletId: primaryWalletId,
                destinationWalletId: destinationWalletId,
                primaryCategoryId: primaryCategoryId,
                relatedTransactionId: relatedTransactionId,
                importBatchId: importBatchId,
                idempotencyKey: idempotencyKey,
                location: location,
                createdAt: createdAt,
                updatedAt: updatedAt,
                rowid: rowid,
              ),
          createCompanionCallback:
              ({
                required String id,
                required String type,
                required int amount,
                Value<String> currency = const Value.absent(),
